import { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ArrowLeft } from 'lucide-react';

const TRANSITION_MS = 900;

// Replaced at build time with a base64 data: URI of the compressed source
// video (day field -> forest -> night city -> day field, ~40s loop).
const VIDEO_SRC = 'data:video/mp4;base64,';

const DEMO_USERS = {
  arjun_verma: {
    punya: {
      count: 142,
      summary:
        'Consistently shows up for friends in a crisis, and has driven two hours just to bring someone soup when they were sick.',
    },
    paapa: {
      count: 8,
      summary:
        'Has a well-documented habit of "borrowing" chargers and never returning them. Once finished the last samosa at a family gathering without shame.',
    },
  },
  priya_nair: {
    punya: {
      count: 289,
      summary: "Organized the building's Diwali cleanup three years running, and never forgets a birthday.",
    },
    paapa: {
      count: 3,
      summary: 'Occasionally vanishes from group chats for weeks, then reappears like nothing happened.',
    },
  },
  rahul_gupta: {
    punya: {
      count: 76,
      summary: 'A great listener, though famously terrible at keeping secrets he finds genuinely funny.',
    },
    paapa: {
      count: 21,
      summary: 'Notorious for reply-all mishaps, and parks exactly one inch over the line every single time.',
    },
  },
  ananya_iyer: {
    punya: {
      count: 401,
      summary:
        'The person everyone calls first with good news. Has personally talked three friends out of terrible haircuts.',
    },
    paapa: {
      count: 5,
      summary: "Will spoil a show if you haven't finished it yet, with zero warning.",
    },
  },
  karan_mehta: {
    punya: {
      count: 58,
      summary: 'Always splits the bill fairly, down to the last rupee, and never makes it awkward.',
    },
    paapa: {
      count: 34,
      summary: 'Chronically fifteen minutes late, and has never once apologized for it.',
    },
  },
  diya_shah: {
    punya: {
      count: 210,
      summary: 'Adopted two street dogs and talked the whole neighborhood into helping feed them.',
    },
    paapa: {
      count: 12,
      summary: 'Sends voice notes that run four minutes long, even for simple questions.',
    },
  },
};

function cx(...parts) {
  return parts.filter(Boolean).join(' ');
}

function PrayingHandsIcon({ className, style }) {
  return (
    <svg viewBox="0 0 48 48" className={className} style={style} fill="none" aria-hidden="true">
      <path d="M24 4C17 10 14 18 14 26c0 6 2 11 5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M24 4c7 6 10 14 10 22 0 6-2 11-5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M24 4v37" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M15 33c2.8 2.3 6 3.5 9 3.5s6.2-1.2 9-3.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M17 12c-1 3-1.5 6-1.5 9" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" opacity="0.55" />
      <path d="M31 12c1 3 1.5 6 1.5 9" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" opacity="0.55" />
    </svg>
  );
}

function SkullIcon({ className, style }) {
  return (
    <svg viewBox="0 0 48 48" className={className} style={style} fill="none" aria-hidden="true">
      <path
        d="M24 6c-8.3 0-15 6.5-15 14.5 0 5.2 2.2 8.7 4.5 11v6.5c0 1.1.9 2 2 2h1.5v-4.5h3v4.5h8v-4.5h3v4.5H33c1.1 0 2-.9 2-2V31.5c2.3-2.3 4.5-5.8 4.5-11C39.5 12.5 32.8 6 24 6Z"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinejoin="round"
        fill="currentColor"
        fillOpacity="0.08"
      />
      <circle cx="18.5" cy="21" r="3" fill="currentColor" />
      <circle cx="29.5" cy="21" r="3" fill="currentColor" />
      <path d="M24 24.5v4.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M18.5 33.5h11" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M21 33.5v3M24 33.5v3M27 33.5v3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

function usePrefersReducedMotion() {
  return useMemo(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }, []);
}

export default function ChitraguptaDemo() {
  const [view, setView] = useState('landing'); // 'landing' | 'opening' | 'profile' | 'closing'
  const [coversOpen, setCoversOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [activeIndex, setActiveIndex] = useState(-1);
  const [suggestionsDismissed, setSuggestionsDismissed] = useState(false);
  const [selectedUsername, setSelectedUsername] = useState(null);
  const inputRef = useRef(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  const suggestions = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (q.length < 3) return [];
    return Object.keys(DEMO_USERS)
      .filter((u) => u.toLowerCase().includes(q))
      .slice(0, 5);
  }, [query]);
  const showSuggestions = !suggestionsDismissed && suggestions.length > 0;

  useEffect(() => {
    if (view === 'opening') {
      setCoversOpen(false);
      const raf = requestAnimationFrame(() => setCoversOpen(true));
      const t = window.setTimeout(() => setView('profile'), TRANSITION_MS);
      return () => {
        cancelAnimationFrame(raf);
        window.clearTimeout(t);
      };
    }
    if (view === 'closing') {
      setCoversOpen(true);
      const raf = requestAnimationFrame(() => setCoversOpen(false));
      const t = window.setTimeout(() => {
        setView('landing');
        setSelectedUsername(null);
      }, TRANSITION_MS);
      return () => {
        cancelAnimationFrame(raf);
        window.clearTimeout(t);
      };
    }
    return undefined;
  }, [view]);

  function selectUser(username) {
    setSelectedUsername(username);
    setQuery('');
    setActiveIndex(-1);
    setSuggestionsDismissed(true);
    if (prefersReducedMotion) {
      setView('profile');
      return;
    }
    setView('opening');
  }

  function goBack() {
    if (prefersReducedMotion) {
      setView('landing');
      setSelectedUsername(null);
      return;
    }
    setView('closing');
  }

  function handleKeyDown(e) {
    if (suggestions.length === 0) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex((i) => (i + 1) % suggestions.length);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex((i) => (i - 1 + suggestions.length) % suggestions.length);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const pick = suggestions[activeIndex] ?? suggestions[0];
      if (pick) selectUser(pick);
    } else if (e.key === 'Escape') {
      setSuggestionsDismissed(true);
    }
  }

  const baseView = view === 'landing' ? 'landing' : 'profile';
  const overlayVisible = view === 'opening' || view === 'closing';
  const user = selectedUsername ? DEMO_USERS[selectedUsername] : null;

  return (
    <div className="cg-root" style={{ fontFamily: "'Karla', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Karla:wght@400;500;600;700&display=swap');

        .cg-root { position: relative; width: 100%; overflow: hidden; border-radius: 20px; color: #2B2118; }
        .cg-display { font-family: 'Fraunces', Georgia, serif; }

        .cg-sky {
          position: relative;
          min-height: 580px;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          overflow: hidden;
          /* Static fallback shown before the video paints, or if it fails to load. */
          background: linear-gradient(180deg, #6FB7E6 0%, #BFE0EF 38%, #FBE1AE 78%, #F3C574 100%);
        }
        .cg-bg-video {
          position: absolute; inset: 0; width: 100%; height: 100%;
          object-fit: cover; object-position: center;
        }
        .cg-sky-scrim {
          position: absolute; inset: 0;
          background: linear-gradient(180deg, rgba(10,8,4,0.45) 0%, rgba(10,8,4,0.12) 45%, rgba(10,8,4,0.28) 100%);
          pointer-events: none;
        }
        .cg-wordmark {
          color: #FBF6E8;
          text-shadow: 0 2px 14px rgba(0,0,0,0.6), 0 1px 3px rgba(0,0,0,0.7);
        }

        .cg-search-card {
          background: #F3E8CC;
          border: 1px solid rgba(43,33,24,0.15);
          box-shadow: 0 14px 34px rgba(10,8,4,0.4);
        }
        .cg-muted { color: rgba(43,33,24,0.62); }
        .cg-input::placeholder { color: rgba(43,33,24,0.45); }
        .cg-suggestion[data-active="true"], .cg-suggestion:hover { background: rgba(43,33,24,0.07); }

        .cg-book-wrap { perspective: 1800px; }
        .cg-cover {
          position: absolute; inset: 0; width: 50%;
          background: linear-gradient(135deg, #DDCBA0, #B99A63);
          backface-visibility: hidden;
          transition: transform ${TRANSITION_MS}ms cubic-bezier(.45,0,.2,1), opacity ${TRANSITION_MS}ms ease;
          box-shadow: 0 0 46px rgba(0,0,0,0.4);
        }
        .cg-cover-left { left: 0; transform-origin: left center; border-radius: 20px 0 0 20px; }
        .cg-cover-right { right: 0; transform-origin: right center; border-radius: 0 20px 20px 0; }
        .cg-cover-open.cg-cover-left { transform: rotateY(-118deg); opacity: 0; }
        .cg-cover-open.cg-cover-right { transform: rotateY(118deg); opacity: 0; }
        .cg-cover-emblem {
          position: absolute; top: 50%; width: 40px; height: 40px; margin-top: -20px;
          border: 2px solid rgba(43,33,24,0.35); border-radius: 999px;
        }
        .cg-cover-left .cg-cover-emblem { right: 28px; }
        .cg-cover-right .cg-cover-emblem { left: 28px; }

        .cg-notebook { background: linear-gradient(180deg, #EFE3C4, #E4D3A8); min-height: 560px; }
        .cg-page {
          background-image: radial-gradient(rgba(43,33,24,0.035) 1px, transparent 1px);
          background-size: 15px 15px;
        }
        .cg-spine-v {
          position: absolute; top: 0; bottom: 0; left: 50%; width: 20px; margin-left: -10px;
          background: linear-gradient(90deg, rgba(0,0,0,0.14), rgba(0,0,0,0) 32%, rgba(0,0,0,0) 68%, rgba(0,0,0,0.14));
          pointer-events: none;
        }
        .cg-spine-h {
          height: 20px; margin: 0 -1px;
          background: linear-gradient(180deg, rgba(0,0,0,0.14), rgba(0,0,0,0) 32%, rgba(0,0,0,0) 68%, rgba(0,0,0,0.14));
        }
        .cg-corner-curl {
          position: absolute; right: 0; bottom: 0; width: 36px; height: 36px;
          background: linear-gradient(135deg, transparent 50%, rgba(0,0,0,0.16) 50%);
          border-radius: 0 0 6px 0;
        }

        .cg-punya-text { color: #28477A; }
        .cg-paapa-text { color: #8C2F26; }
        .cg-punya-icon { color: #2E5A9E; }
        .cg-paapa-icon { color: #A3392E; }
        .cg-count { font-variant-numeric: tabular-nums; }

        .cg-focusable:focus-visible { outline: 2px solid #C99A3E; outline-offset: 2px; }
      `}</style>

      {baseView === 'landing' && (
        <div className="cg-sky">
          <video
            className="cg-bg-video"
            src={VIDEO_SRC}
            autoPlay={!prefersReducedMotion}
            loop
            muted
            playsInline
            preload="auto"
            aria-hidden="true"
          />
          <div className="cg-sky-scrim" />

          <div className="cg-wordmark relative z-10 flex flex-col items-center px-6 text-center">
            <h1 className="cg-display text-4xl sm:text-5xl font-medium mb-1">Chitragupta</h1>
            <p className="cg-display text-sm sm:text-base mb-8 opacity-90">the ledger of deeds</p>

            <div className="cg-search-card rounded-2xl p-3 w-80 sm:w-96 text-left relative">
              <label htmlFor="cg-search" className="block text-xs cg-muted mb-1 px-1">
                Find someone&rsquo;s ledger
              </label>
              <div className="flex items-center gap-2 px-2">
                <Search size={18} className="cg-muted flex-shrink-0" aria-hidden="true" />
                <input
                  id="cg-search"
                  ref={inputRef}
                  role="combobox"
                  aria-expanded={showSuggestions}
                  aria-controls="cg-suggestion-list"
                  aria-autocomplete="list"
                  autoComplete="off"
                  className="cg-input cg-focusable w-full bg-transparent py-2 outline-none text-base"
                  placeholder="Type a username"
                  value={query}
                  onChange={(e) => {
                    setQuery(e.target.value);
                    setActiveIndex(-1);
                    setSuggestionsDismissed(false);
                  }}
                  onFocus={() => setSuggestionsDismissed(false)}
                  onBlur={() => setSuggestionsDismissed(true)}
                  onKeyDown={handleKeyDown}
                />
              </div>

              {query.trim().length > 0 && query.trim().length < 3 && (
                <p className="text-xs cg-muted px-3 pt-1">Keep typing — 3+ characters shows suggestions</p>
              )}

              {showSuggestions && (
                <ul id="cg-suggestion-list" role="listbox" className="mt-2 border-t border-black/10 pt-1">
                  {suggestions.map((username, i) => (
                    <li key={username} role="option" aria-selected={i === activeIndex}>
                      <button
                        type="button"
                        data-active={i === activeIndex}
                        className="cg-suggestion cg-focusable w-full text-left px-3 py-2 rounded-lg text-sm"
                        onMouseDown={(e) => {
                          e.preventDefault();
                          selectUser(username);
                        }}
                      >
                        @{username}
                      </button>
                    </li>
                  ))}
                </ul>
              )}

              {query.trim().length >= 3 && suggestions.length === 0 && (
                <p className="text-xs cg-muted px-3 pt-1">No one&rsquo;s ledger found for &ldquo;{query.trim()}&rdquo;</p>
              )}
            </div>
          </div>
        </div>
      )}

      {baseView === 'profile' && user && (
        <div className="cg-notebook relative p-4 sm:p-8">
          <button
            type="button"
            onClick={goBack}
            className="cg-focusable inline-flex items-center gap-1.5 text-sm cg-muted mb-4 px-2 py-1 rounded-lg"
          >
            <ArrowLeft size={16} aria-hidden="true" />
            Back to search
          </button>

          <h2 className="cg-display text-2xl sm:text-3xl font-medium text-center mb-6">
            @{selectedUsername}
          </h2>

          <div className="relative flex flex-col md:flex-row rounded-xl overflow-hidden" style={{ boxShadow: '0 18px 40px rgba(20,14,6,0.28)' }}>
            <section className="cg-page flex-1 p-6 sm:p-8">
              <div className="flex items-center gap-3 mb-3">
                <PrayingHandsIcon className="cg-punya-icon" style={{ width: 34, height: 34 }} />
                <div>
                  <h3 className="cg-display text-lg font-medium cg-punya-text">Punya</h3>
                  <p className="text-xs cg-muted">the good stuff</p>
                </div>
              </div>
              <p className="cg-display cg-count text-5xl font-medium cg-punya-text mb-3">{user.punya.count}</p>
              <p className="text-sm leading-relaxed">{user.punya.summary}</p>
            </section>

            <div className="cg-spine-v hidden md:block" />
            <div className="cg-spine-h block md:hidden" />

            <section className="cg-page flex-1 p-6 sm:p-8 relative">
              <div className="flex items-center gap-3 mb-3">
                <SkullIcon className="cg-paapa-icon" style={{ width: 34, height: 34 }} />
                <div>
                  <h3 className="cg-display text-lg font-medium cg-paapa-text">Paapa</h3>
                  <p className="text-xs cg-muted">the questionable stuff</p>
                </div>
              </div>
              <p className="cg-display cg-count text-5xl font-medium cg-paapa-text mb-3">{user.paapa.count}</p>
              <p className="text-sm leading-relaxed">{user.paapa.summary}</p>
              <div className="cg-corner-curl" />
            </section>
          </div>
        </div>
      )}

      {overlayVisible && (
        <div className="cg-book-wrap absolute inset-0 z-20">
          <div className={cx('cg-cover cg-cover-left', coversOpen && 'cg-cover-open')}>
            <div className="cg-cover-emblem" />
          </div>
          <div className={cx('cg-cover cg-cover-right', coversOpen && 'cg-cover-open')}>
            <div className="cg-cover-emblem" />
          </div>
        </div>
      )}
    </div>
  );
}
